-- ============================================================
-- Helper stored procedures for the Medallion ELT Framework
-- Run against the Azure SQL Database metadata store
-- ============================================================

-- ============================================================
-- ctrl.usp_upsert_watermark
-- Called at the end of a successful pipeline run to record
-- the latest load date and optional high-watermark timestamp
-- ============================================================
CREATE OR ALTER PROCEDURE ctrl.usp_upsert_watermark
    @SourceTableId   INT,
    @LastLoadDate    DATE,
    @LastWatermarkTS DATETIME2 = NULL
AS
BEGIN
    SET NOCOUNT ON;
    MERGE ctrl.Watermark AS tgt
    USING (
        SELECT
            @SourceTableId   AS SourceTableId,
            @LastLoadDate    AS LastLoadDate,
            @LastWatermarkTS AS LastWatermarkTS
    ) AS src
        ON tgt.SourceTableId = src.SourceTableId
    WHEN MATCHED THEN
        UPDATE SET
            LastLoadDate    = src.LastLoadDate,
            LastWatermarkTS = src.LastWatermarkTS,
            UpdatedDate     = GETDATE()
    WHEN NOT MATCHED THEN
        INSERT (SourceTableId, LastLoadDate, LastWatermarkTS)
        VALUES (src.SourceTableId, src.LastLoadDate, src.LastWatermarkTS);
END;
GO

-- ============================================================
-- ctrl.usp_log_execution_start
-- Inserts a RUNNING row into PipelineExecution and returns
-- the new ExecutionId so the pipeline can update it later.
-- In Synapse pipelines, call via Lookup Activity (SELECT output).
-- ============================================================
CREATE OR ALTER PROCEDURE ctrl.usp_log_execution_start
    @PipelineName        NVARCHAR(200),
    @RunId               NVARCHAR(100),
    @SourceTableId       INT            = NULL,
    @SourceConnectionName NVARCHAR(200) = NULL,
    @TableName           NVARCHAR(200)  = NULL,
    @Layer               NVARCHAR(20),
    @LoadDate            DATE           = NULL
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO ctrl.PipelineExecution
        (PipelineName, RunId, SourceTableId, SourceConnectionName, TableName, Layer, LoadDate, Status)
    VALUES
        (@PipelineName, @RunId, @SourceTableId, @SourceConnectionName, @TableName, @Layer, @LoadDate, 'RUNNING');
    SELECT CAST(SCOPE_IDENTITY() AS INT) AS ExecutionId;
END;
GO

-- ============================================================
-- ctrl.usp_log_execution_end
-- Closes an execution row with final status, row counts, and
-- any error message.  Called by both success and failure paths.
-- ============================================================
CREATE OR ALTER PROCEDURE ctrl.usp_log_execution_end
    @RunId        NVARCHAR(100),
    @Layer        NVARCHAR(20),
    @Status       NVARCHAR(20),
    @RowsRead     BIGINT         = NULL,
    @RowsWritten  BIGINT         = NULL,
    @ErrorMessage NVARCHAR(MAX)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE ctrl.PipelineExecution
    SET
        EndTime      = GETDATE(),
        Status       = @Status,
        RowsRead     = @RowsRead,
        RowsWritten  = @RowsWritten,
        ErrorMessage = @ErrorMessage
    WHERE RunId = @RunId
      AND Layer = @Layer;
END;
GO
